#include <print>
#include <vector>

int greedy(int n) {
    int coins[] = {4, 3, 1};
    int used = 0;
    for (int c : coins) { used += n / c; n %= c; }
    return used;
}

int best(int n) {
    int r = n + 1;
    for (int a = 0; a * 4 <= n; ++a)
        for (int b = 0; b * 3 <= n - a * 4; ++b) {
            int tot = a + b + (n - a * 4 - b * 3);
            if (tot < r) r = tot;
        }
    return r;
}

int main() {
    std::vector<int> bad;
    for (int n = 1; n <= 60; ++n)
        if (greedy(n) != best(n)) bad.push_back(n);
    std::println("面额 4/3/1，1 到 60 元：贪心翻车 {} 笔", bad.size());
    std::println("6 元：贪心 {} 张，最优 {} 张", greedy(6), best(6));
    // 只用眼睛找出的两张拿法：3 + 3 = 6
    // 敢用贪心的时候：拿枚举在真实金额范围里逐笔验过，或说得出大的那张永远不亏的理由
    return 0;
}

